import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.DZhUhjDB.js";const u=JSON.parse('{"title":"🎯 Módulo 02 — Detection Engineering y Métricas de Detección","description":"","frontmatter":{"title":"🎯 Módulo 02 — Detection Engineering y Métricas de Detección"},"headers":[],"relativePath":"modules/purple-team/02-detection-engineering.md","filePath":"modules/purple-team/02-detection-engineering.md","lastUpdated":1787330151000}'),i={name:"modules/purple-team/02-detection-engineering.md"};function d(o,e,r,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="🎯-modulo-02-—-detection-engineering-y-metricas-de-deteccion" tabindex="-1">🎯 Módulo 02 — Detection Engineering y Métricas de Detección</h1><blockquote><p><strong>Nivel:</strong> Avanzado · <strong>Área:</strong> Purple Team</p><p>Objetivo: convertir conocimiento ofensivo (ATT&amp;CK) en <strong>detecciones de producción</strong>, y <strong>medir</strong> si de verdad funcionan. Esto es el puente profesional entre Red y Blue.</p></blockquote><hr><h2 id="indice" tabindex="-1">Índice</h2><ol><li><a href="#1-qué-es-detection-engineering">Qué es Detection Engineering</a></li><li><a href="#2-el-ciclo-de-vida-de-una-detección">El ciclo de vida de una detección</a></li><li><a href="#3-fuentes-de-telemetría-qué-datos-necesitas">Fuentes de telemetría (qué datos necesitas)</a></li><li><a href="#4-tipos-de-detección">Tipos de detección</a></li><li><a href="#5-métricas-de-detección-medir-si-sirve">Métricas de detección (medir si sirve)</a></li><li><a href="#6-coverage-attck-cobertura">Coverage ATT&amp;CK (cobertura)</a></li><li><a href="#7-detection-as-code">Detection-as-code</a></li><li><a href="#8-referencias">Referencias</a></li></ol><hr><h2 id="_1-que-es-detection-engineering" tabindex="-1">1. Qué es Detection Engineering</h2><blockquote><p><em>&quot;Una detección que nadie probó y que nadie mide, es una promesa, no una defensa.&quot;</em></p></blockquote><p><strong>Detection engineering</strong> es la disciplina de <strong>diseñar, probar, desplegar y mantener</strong> detecciones de seguridad. A diferencia del threat hunting (buscar ad hoc), el detection engineer:</p><ul><li>Convierte una técnica ATT&amp;CK en una <strong>regla reproducible</strong>.</li><li>La <strong>valida</strong> (¿dispara con un ataque real? ¿da falsos positivos?).</li><li>La <strong>mide</strong> (¿cuánto ruido genera? ¿detecta lo que debe?).</li><li>La <strong>mantiene</strong> (ajusta umbrales, exclusiones).</li></ul><hr><h2 id="_2-el-ciclo-de-vida-de-una-deteccion" tabindex="-1">2. El ciclo de vida de una detección</h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. Requirement   ← ¿Qué amenaza/ técnica queremos detectar? │</span></span>
<span class="line"><span>│ 2. Data          ← ¿Tenemos la telemetría necesaria?        │</span></span>
<span class="line"><span>│ 3. Detection     ← Escribir la regla (Sigma/YARA/SIEM)      │</span></span>
<span class="line"><span>│ 4. Test          ← Validar con emulación (Atomic/CALDERA)   │</span></span>
<span class="line"><span>│ 5. Deploy        ← Publicar al SIEM/EDR                    │</span></span>
<span class="line"><span>│ 6. Measure        ← MTTD, FP rate, cobertura               │</span></span>
<span class="line"><span>│ 7. Tune           ← Ajustar umbrales, exclusiones          │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────┘</span></span></code></pre></div><blockquote><p>La mayoría de equipos solo hace los pasos 1–5 y <strong>nunca mide ni afina</strong>. Ahí se acumula el ruido y muere el SOC.</p></blockquote><hr><h2 id="_3-fuentes-de-telemetria-que-datos-necesitas" tabindex="-1">3. Fuentes de telemetría (qué datos necesitas)</h2><table tabindex="0"><thead><tr><th>Capa</th><th>Fuente</th><th>Qué te da</th></tr></thead><tbody><tr><td><strong>Endpoint</strong></td><td>Sysmon, EDR (CrowdStrike, S1, Defender)</td><td>Procesos, comandos, DLLs, red de host</td></tr><tr><td><strong>Red</strong></td><td>Suricata, Zeek, NetFlow</td><td>Conexiones, protocolos, payloads</td></tr><tr><td><strong>Identidad</strong></td><td>AD/Entra ID, logs de auth</td><td>Logins, privilegios, cambios</td></tr><tr><td><strong>Aplicación</strong></td><td>WAF, logs web</td><td>Ataques web, rutas, payloads</td></tr><tr><td><strong>Cloud</strong></td><td>CloudTrail, Azure Activity</td><td>Acciones de API, cambios IAM</td></tr></tbody></table><blockquote><p><strong>Regla:</strong> si no tienes la telemetría, <strong>primero habilítala</strong> (ej. Sysmon con buena config), o tu detección será ciega. Ver <a href="./../../02-SEGURIDAD-INFORMACION/02-blue-team-defensa/siem-wazuh/"><code>../siem-wazuh</code></a> para Sysmon/Suricata.</p></blockquote><hr><h2 id="_4-tipos-de-deteccion" tabindex="-1">4. Tipos de detección</h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Cómo funciona</th><th>Pros</th><th>Contras</th></tr></thead><tbody><tr><td><strong>Signature-based</strong></td><td>Busca un patrón exacto (hash, string, IOC)</td><td>Preciso, barato</td><td>Se evade fácil (IOC rota)</td></tr><tr><td><strong>Behavior-based</strong></td><td>Busca comportamiento (parent/child, flags, secuencia)</td><td>Resistente a evasión</td><td>Más complejo, más FP</td></tr><tr><td><strong>Anomaly-based</strong></td><td>Busca desviación del baseline</td><td>Detecta lo desconocido</td><td>Ruido, requiere baseline</td></tr><tr><td><strong>Correlation</strong></td><td>Une múltiples eventos en una historia</td><td>Detecta ataques multi-paso</td><td>Complejo de mantener</td></tr></tbody></table><blockquote><p>La tendencia profesional: <strong>behavior y correlation</strong> sobre <strong>Sysmon/EDR</strong>, no solo hashes e IOCs.</p></blockquote><hr><h2 id="_5-metricas-de-deteccion-medir-si-sirve" tabindex="-1">5. Métricas de detección (medir si sirve)</h2><p>Usa la <strong>matriz de confusión</strong> como base:</p><table tabindex="0"><thead><tr><th></th><th>Realmente ataque</th><th>Realmente benigno</th></tr></thead><tbody><tr><td><strong>Alerta disparada</strong></td><td>TP (True Positive)</td><td>FP (False Positive)</td></tr><tr><td><strong>Sin alerta</strong></td><td>FN (False Negative)</td><td>TN (True Negative)</td></tr></tbody></table><h3 id="_5-1-metricas-clave" tabindex="-1">5.1 Métricas clave</h3><table tabindex="0"><thead><tr><th>Métrica</th><th>Fórmula</th><th>Qué significa</th><th>Meta típica</th></tr></thead><tbody><tr><td><strong>Precision (PPV)</strong></td><td><code>TP / (TP + FP)</code></td><td>De las alertas, ¿cuántas eran reales?</td><td>&gt; 70%</td></tr><tr><td><strong>Recall / Sensitivity</strong></td><td><code>TP / (TP + FN)</code></td><td>De los ataques, ¿cuántos detecté?</td><td>&gt; 80%</td></tr><tr><td><strong>False Positive Rate</strong></td><td><code>FP / (FP + TN)</code></td><td>Ruido generado</td><td>&lt; 1%</td></tr><tr><td><strong>MTTD</strong> (Mean Time To Detect)</td><td>tiempo medio desde compromiso a detección</td><td>Velocidad de detección</td><td>minutos/horas</td></tr><tr><td><strong>MTTR</strong> (Mean Time To Respond)</td><td>tiempo medio de detección a contención</td><td>Velocidad de respuesta</td><td>horas</td></tr></tbody></table><h3 id="_5-2-ejemplo-practico" tabindex="-1">5.2 Ejemplo práctico</h3><p>Una regla de fuerza bruta disparó 100 alertas en una semana:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TP = 70 (fuerzas brutas reales)</span></span>
<span class="line"><span>FP = 30 (usuarios que olvidaron su password)</span></span>
<span class="line"><span>FN = 10 (fuerzas brutas no detectadas)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Precision = 70 / (70+30) = 70%</span></span>
<span class="line"><span>Recall    = 70 / (70+10) = 87.5%</span></span></code></pre></div><p>→ La regla es buena en recall pero genera 30% de ruido. <strong>Acción:</strong> subir el umbral (de 5 a 10 intentos) y excluir IPs internas conocidas.</p><h3 id="_5-3-el-trade-off-fundamental" tabindex="-1">5.3 El trade-off fundamental</h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Subir umbral (más estricto)  →  menos FP (más precision), pero más FN (menos recall)</span></span>
<span class="line"><span>Bajar umbral (más sensible)  →  más TP (más recall), pero más FP (menos precision)</span></span></code></pre></div><p>No hay detección perfecta: <strong>eliges</strong> el punto de operación según tu tolerancia al ruido.</p><hr><h2 id="_6-coverage-att-ck-cobertura" tabindex="-1">6. Coverage ATT&amp;CK (cobertura)</h2><p>La cobertura responde: <strong>¿qué porcentaje de técnicas ATT&amp;CK tenemos cubierto por al menos una detección?</strong></p><h3 id="_6-1-metodo" tabindex="-1">6.1 Método</h3><ol><li>Toma las técnicas relevantes para tu organización (no todas las ~200).</li><li>Marca por cada técnica: <code>detectada</code> / <code>parcial</code> / <code>no detectada</code>.</li><li>Usa <strong>ATT&amp;CK Navigator</strong> para visualizarlo.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ATT&amp;CK Navigator (web): https://mitre-attack.github.io/attack-navigator/</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exporta tu layer JSON y guárdalo versionado en el repo</span></span></code></pre></div><h3 id="_6-2-tabla-de-cobertura-plantilla" tabindex="-1">6.2 Tabla de cobertura (plantilla)</h3><table tabindex="0"><thead><tr><th>Técnica</th><th>Detección</th><th>Fuente</th><th>Estado</th><th>Cobertura</th></tr></thead><tbody><tr><td>T1059.001 PowerShell</td><td>Regla Sigma <code>powershell_encoded</code></td><td>Sysmon EID 1</td><td>Activa</td><td>✅</td></tr><tr><td>T1110 Brute Force</td><td>Regla Wazuh <code>100101</code></td><td>auth.log</td><td>Activa</td><td>✅</td></tr><tr><td>T1003.001 LSASS dump</td><td>Regla Sigma <code>lsass_access</code></td><td>Sysmon EID 10</td><td>En test</td><td>🟡</td></tr><tr><td>T1547 Registry Run</td><td>—</td><td>—</td><td>Sin cobertura</td><td>❌</td></tr></tbody></table><blockquote><p><strong>Métrica:</strong> <code>cobertura = técnicas detectadas / técnicas relevantes</code>. Meta inicial: cubrir el <strong>ATT&amp;CK Top 10</strong> de técnicas más usadas.</p></blockquote><hr><h2 id="_7-detection-as-code" tabindex="-1">7. Detection-as-code</h2><p>Las detecciones deben tratarse como <strong>código</strong>: versionadas, revisadas y desplegadas con CI/CD.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reglas/</span></span>
<span class="line"><span>├── sigma/</span></span>
<span class="line"><span>│   ├── windows/</span></span>
<span class="line"><span>│   │   └── powershell_encoded.yml</span></span>
<span class="line"><span>│   └── linux/</span></span>
<span class="line"><span>├── wazuh/</span></span>
<span class="line"><span>│   └── local_rules.xml</span></span>
<span class="line"><span>├── yara/</span></span>
<span class="line"><span>│   └── ransomware.yar</span></span>
<span class="line"><span>└── tests/</span></span>
<span class="line"><span>    └── atomic_test_cases.md</span></span></code></pre></div><p>Workflow:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Escribir regla en git</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. PR review (otro analista valida lógica y umbrales)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. CI valida sintaxis (pySigma, yara -c)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. Deploy al SIEM</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5. Medir (sección 5) y documentar</span></span></code></pre></div><p><strong>Entregable de portafolio:</strong> repo de detecciones versionado + tabla de cobertura ATT&amp;CK + métricas de al menos 3 reglas (precision/recall).</p><hr><h2 id="_8-referencias" tabindex="-1">8. Referencias</h2><ul><li><a href="https://mitre-attack.github.io/attack-navigator/" target="_blank" rel="noreferrer">MITRE ATT&amp;CK Navigator</a></li><li><a href="https://github.com/SigmaHQ/sigma" target="_blank" rel="noreferrer">SigmaHQ</a></li><li><a href="https://github.com/redcanaryco/atomic-red-team" target="_blank" rel="noreferrer">Atomic Red Team (para validar detecciones)</a> → ver <a href="./../03-adversary-emulation/"><code>../03-adversary-emulation</code></a></li><li><a href="https://www.detectionengineering.net/" target="_blank" rel="noreferrer">Detection Engineering (libro de referencia)</a></li></ul><hr><p><strong><a href="./../README">⬅ Volver al README de Purple Team</a></strong> · <strong><a href="./../03-adversary-emulation/">→ Adversary Emulation</a></strong></p>`,56)])])}const h=t(i,[["render",d]]);export{u as __pageData,h as default};
